const docs = (function(){ try { return $('Leer comprobantes sin conciliar').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })().filter(d => d.CLASIFICACION !== 'COMPROBANTE_EGRESO')
  .filter(d => ['PROCESADO','SIN_MATCH'].includes(d.ESTADO)); // SIN_MATCH se reintenta: el extracto llega al día siguiente
// Los comprobantes de egreso (pagos a transportistas) los procesa WF-08, no este flujo.
const movs = (function(){ try { return $('Leer movimientos bancarios').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const out = [];
const parseF = v => { if (!v) return null; if (v instanceof Date) return v;
  if (typeof v === 'number' && v > 20000 && v < 80000) return new Date(Date.UTC(1899,11,30) + Math.round(v)*86400000);
  const s = String(v).trim();
  if (/^\d+$/.test(s)) { const n = parseInt(s); if (n > 20000 && n < 80000) return new Date(Date.UTC(1899,11,30) + n*86400000); }
  let m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
  if (m) return new Date(m[3] + '-' + m[2].padStart(2,'0') + '-' + m[1].padStart(2,'0'));
  const d2 = new Date(s.replace(' ', 'T')); return isNaN(d2) ? null : d2; };
const norm = s => String(s || '').toUpperCase().normalize('NFD').replace(/[^A-Z0-9 ]/g, '');
for (const d of docs) {
  const val = parseFloat(d.OCR_VALOR);
  if (!val) { out.push({ json: { ...d, match: 'ERROR', motivo: 'OCR sin valor' } }); continue; }
  const fechaDoc = parseF(d.OCR_FECHA_PAGO);
  // 1) Match exacto: valor igual, ingreso, fecha ±3 días, sin conciliación previa
  let candidatos = movs.filter(m => {
    if (m.ID_CONCILIACION) return false;
    if (m.TIPO !== 'INGRESO') return false;
    if (Math.abs(parseFloat(m.VALOR) - val) > 1) return false;
    const fm = parseF(m.FECHA);
    if (fechaDoc && fm) { const diff = Math.abs((fm - fechaDoc) / 86400000); if (diff > 3) return false; }
    // fecha ilegible (cargas viejas con serial) → no descartar: deciden valor y desempates
    return true;
  });
  // 2) Desempate por nombre de cliente
  if (candidatos.length > 1 && d.OCR_CLIENTE) {
    const nc = norm(d.OCR_CLIENTE).split(' ').filter(w => w.length > 3);
    const filtered = candidatos.filter(m => nc.some(w => norm(m.TERCERO).includes(w)));
    if (filtered.length >= 1) candidatos = filtered;
  }
  // Desempate adicional: la ID de compra informada por el asesor aparece en la referencia/descripción del movimiento
  if (candidatos.length > 1 && d.ID_COMPRA_INFORMADO) {
    const idc = String(d.ID_COMPRA_INFORMADO);
    const byId = candidatos.filter(m => (String(m.REFERENCIA||'') + ' ' + String(m.DESCRIPCION||'') + ' ' + String(m.FACTURA_OC||'')).includes(idc));
    if (byId.length >= 1) candidatos = byId;
  }
  if (candidatos.length === 1) {
    out.push({ json: { ...d, match: 'OK', metodo: 'AUTO_VALOR_FECHA', mov: candidatos[0] } });
  } else if (candidatos.length === 0) {
    if (d.ESTADO === 'SIN_MATCH') continue; // ya estaba marcado: reintento silencioso, sin re-alertar
    out.push({ json: { ...d, match: 'SIN_MATCH', motivo: 'Ningún movimiento coincide (puede que el extracto aún no esté cargado)' } });
  } else {
    out.push({ json: { ...d, match: 'AMBIGUO', motivo: candidatos.length + ' movimientos candidatos', candidatos: candidatos.map(c => c.ID_MOV).join(', ') } });
  }
}
return out;

parameters.query:
insert into conciliacion (
  id_conc, fecha, id_doc_wa, id_mov_banco, valor_comprobante, valor_banco, diferencia,
  metodo_match, estado
) values (
  $1::text, $2::text::date, $3::text, $4::text, $5::text::numeric, $6::text::numeric, 0,
  $7::text, 'OK'
)
on conflict (id_conc) do nothing;

